function metricChart(title,samples,key){const values=samples.map(sample=>sample[key]).filter(value=>value!=null&&value!=='').map(Number).filter(Number.isFinite);if(values.length<2)return `<section class="metric-chart"><h3>${esc(title)}</h3><div class="empty compact"><p>Not enough history yet.</p></div></section>`;const max=Math.max(...values,1),points=values.map((value,index)=>`${index/(values.length-1)*100},${100-value/max*90}`).join(' ');return `<section class="metric-chart"><h3>${esc(title)}</h3><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="${esc(title)} history"><polyline points="${points}"/></svg></section>`}
