function monitorPolicy(){const name=localStorage.getItem('nuvrion.monitor.sensitivity')??'balanced',profiles={sensitive:{warning:60,critical:80},balanced:{warning:75,critical:90},relaxed:{warning:85,critical:95}};return {name,...(profiles[name]??profiles.balanced)}}
function vmPressure(resource){const metric=state.performanceLatest[resource.id]??{},configured=Number(resource.attributes?.memoryBytes),cpu=Number.isFinite(Number(metric.cpuUtilizationPercent))?Number(metric.cpuUtilizationPercent):null,memory=Number.isFinite(Number(metric.memoryUtilizationPercent))?Number(metric.memoryUtilizationPercent):Number.isFinite(Number(metric.memoryUsedBytes))&&configured>0?Number(metric.memoryUsedBytes)/configured*100:null,score=Math.max(cpu??-1,memory??-1),policy=monitorPolicy(),severity=score<0?'unavailable':score>=policy.critical?'critical':score>=policy.warning?'warning':'normal',observedAt=metric.observedAt??resource.observedAt,age=observedAt?Date.now()-Date.parse(observedAt):Infinity;return {resource,metric,cpu,memory,score,severity,observedAt,fresh:age<=120000}}
