async function applySnapshotRetention(){const resource=state.resources.find(item=>item.id===state.snapshotResourceId),candidates=snapshotRetentionCandidates().sort((a,b)=>(Number(b.depth)||0)-(Number(a.depth)||0)||String(a.createdAt??'').localeCompare(String(b.createdAt??'')));if(!resource||!candidates.length)return;const names=candidates.slice(0,4).map(item=>`“${item.name}”`).join(', '),more=candidates.length>4?` and ${candidates.length-4} more`:'';if(!window.confirm(`Delete ${candidates.length} retention-eligible snapshot${candidates.length===1?'':'s'} for ${resource.name}: ${names}${more}? Each recovery point will be removed permanently and VMware will consolidate its disks.`))return;setSnapshotBusy(`Deleting ${candidates.length} snapshot${candidates.length===1?'':'s'} and consolidating disks…`);$('snapshot-error').textContent='';let deleted=0;try{for(const snapshot of candidates){await api(`/resources/${resource.id}/snapshots/${encodeURIComponent(snapshot.id)}`,{method:'DELETE'});deleted++}await loadSnapshots();notice(`${deleted} snapshot${deleted===1?'':'s'} deleted by retention review.`)}catch(error){await loadSnapshots().catch(()=>{});$('snapshot-error').textContent=`${deleted} snapshot${deleted===1?'':'s'} deleted before VMware stopped the retention operation. ${error.message}`;setSnapshotBusy('')}}
