const collectVmSettingsBasic=collectVmSettings;collectVmSettings=function(){const output=collectVmSettingsBasic(),num=id=>Number($(id).value);Object.assign(output,{cpuReservationMHz:num('settings-cpu-reservation'),cpuLimitMHz:num('settings-cpu-limit'),cpuSharesLevel:$('settings-cpu-shares-level').value,cpuShares:num('settings-cpu-shares'),memoryReservationMB:num('settings-memory-reservation'),memoryLimitMB:num('settings-memory-limit'),memorySharesLevel:$('settings-memory-shares-level').value,memoryShares:num('settings-memory-shares'),memoryReservationLockedToMax:$('settings-memory-locked').checked,iommuEnabled:$('settings-iommu').checked,vPMCEnabled:$('settings-vpmc').checked,cpuAffinity:parseCpuAffinity($('settings-cpu-affinity').value)});output.disks=[...document.querySelectorAll('[data-settings-disk]')].map(row=>({id:row.dataset.settingsDisk,capacityBytes:Math.round(Number(row.querySelector('[data-settings-disk-size]').value)*1073741824),sharesLevel:row.querySelector('[data-settings-disk-shares-level]').value,shares:Number(row.querySelector('[data-settings-disk-shares]').value),limitIOps:Number(row.querySelector('[data-settings-disk-iops]').value),diskMode:row.querySelector('[data-settings-disk-mode]').value,sharing:row.querySelector('[data-settings-disk-sharing]').value}));output.controllers=[...document.querySelectorAll('[data-settings-controller]')].filter(row=>row.querySelector('[data-settings-controller-sharing]')).map(row=>({id:row.dataset.settingsController,busSharing:row.querySelector('[data-settings-controller-sharing]').value}));return output};
