function settingsSelect(id,value,items,disabled=false){return `<select ${id?`id="${id}"`:''} ${disabled?'disabled':''}>${items.map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${label}</option>`).join('')}</select>`}
function settingsCheck(id,label,value,disabled=false){return `<label class="settings-check"><input id="${id}" type="checkbox" ${value?'checked':''} ${disabled?'disabled':''}> ${label}</label>`}
function settingsOptionGroup(icon,title,summary,body,open=false){return `<details class="vm-settings-device vm-option-group" ${open?'open':''}><summary><span>${vmHardwareSvg[icon]}</span><strong>${title}</strong><em>${summary}</em></summary><div class="settings-detail-grid">${body}</div></details>`}
function renderCompleteVmOptions(settings){
  const on=settings.powerState==='poweredOn',offOnly=on?'disabled':'',boolValue=value=>value===true;
  $('vm-settings-options').innerHTML=[
    settingsOptionGroup('general','General Options',settings.name??'',`<label>VM Name<input id="settings-name" maxlength="80" required value="${esc(settings.name??'')}"></label><label>Guest operating system<input id="settings-guest" readonly value="${esc([settings.guestId,settings.hardwareVersion].filter(Boolean).join(' · '))}"></label><label class="settings-wide">VM notes<textarea id="settings-annotation" maxlength="1024" rows="2">${esc(settings.annotation??'')}</textarea></label>`,true),
    settingsOptionGroup('video','VMware Remote Console Options','Session behavior',`<label class="settings-check settings-wide"><input type="checkbox" disabled> Lock the guest operating system when the last remote user disconnects</label>`),
    settingsOptionGroup('tools','VMware Tools',settings.syncTimeWithHost?'Time synchronization enabled':'Expand for VMware Tools settings',`<label>Stop${settingsSelect('settings-poweroff-type',settings.powerOffType??'soft',[['hard','Power Off'],['soft','Shut Down Guest'],['preset','System Default'] ],on)}</label><label>Pause${settingsSelect('settings-suspend-type',settings.suspendType??'soft',[['hard','Suspend'],['soft','Put Guest on Standby'],['preset','System Default']],on)}</label><label>Restart${settingsSelect('settings-reset-type',settings.resetType??'soft',[['hard','Reset'],['soft','Restart Guest'],['preset','System Default']],on)}</label>${settingsCheck('settings-tools-poweron','Run script after powering on',boolValue(settings.toolsAfterPowerOn),on)}${settingsCheck('settings-tools-resume','Run script after resuming',boolValue(settings.toolsAfterResume),on)}${settingsCheck('settings-tools-suspend','Run script before suspending',boolValue(settings.toolsBeforeGuestStandby),on)}${settingsCheck('settings-tools-shutdown','Run script before shutting down guest',boolValue(settings.toolsBeforeGuestShutdown),on)}${settingsCheck('settings-tools-upgrade','Check and upgrade VMware Tools before each power on',settings.toolsUpgradePolicy==='upgradeAtPowerCycle')}${settingsCheck('settings-sync-time','Synchronize guest time with host',boolValue(settings.syncTimeWithHost))}`),
    settingsOptionGroup('power','Power management','Standby response and Wake on LAN',`<fieldset class="settings-wide"><legend>Standby response</legend><label><input type="radio" name="settings-standby" value="suspend" ${settings.standbyAction==='suspend'?'checked':''} ${offOnly}> Suspend the virtual machine</label><label><input type="radio" name="settings-standby" value="guestStandby" ${settings.standbyAction!=='suspend'?'checked':''} ${offOnly}> Put the guest OS into standby and leave the VM powered on</label></fieldset><label class="settings-check settings-wide"><input type="checkbox" disabled> Wake on LAN for eligible network adapters</label>`),
    settingsOptionGroup('boot','Boot Options',String(settings.firmware??'bios').toUpperCase(),`<label>Firmware${settingsSelect('settings-firmware',settings.firmware??'bios',[['bios','BIOS'],['efi','EFI']],on)}</label>${settingsCheck('settings-secure-boot','Enable UEFI secure boot',boolValue(settings.secureBoot),settings.firmware!=='efi')}<label>Boot delay (milliseconds)<input id="settings-boot-delay" type="number" min="0" max="600000" step="100" value="${settings.bootDelayMs??0}"></label>${settingsCheck('settings-enter-bios','Force entry into firmware setup on next boot',boolValue(settings.enterBIOSSetup))}${settingsCheck('settings-boot-retry','Automatically retry a failed boot',boolValue(settings.bootRetryEnabled))}<label>Retry after (seconds)<input id="settings-boot-retry-delay" type="number" min="1" max="600" value="${Math.max(1,Math.round((settings.bootRetryDelayMs??10000)/1000))}"></label>`),
    settingsOptionGroup('advanced','Advanced',settings.latencySensitivity??'Normal',`${settingsCheck('settings-disable-acceleration','Disable acceleration',boolValue(settings.disableAcceleration),on)}${settingsCheck('settings-enable-logging','Enable logging',settings.enableLogging!==false,on)}<label>Debugging and statistics${settingsSelect('settings-debug-info',settings.debugInfo??'release',[['release','Run normally'],['debug','Record debugging information'],['stats','Record statistics']])}</label><fieldset class="settings-wide"><legend>Swap file location</legend><label><input type="radio" name="settings-swap" value="inherit" ${(settings.swapPlacement??'inherit')==='inherit'?'checked':''} ${offOnly}> Default (cluster or host setting)</label><label><input type="radio" name="settings-swap" value="vmDirectory" ${settings.swapPlacement==='vmDirectory'?'checked':''} ${offOnly}> Virtual machine directory</label><label><input type="radio" name="settings-swap" value="hostLocal" ${settings.swapPlacement==='hostLocal'?'checked':''} ${offOnly}> Datastore specified by host</label></fieldset><label>Latency sensitivity${settingsSelect('settings-latency',settings.latencySensitivity??'normal',[['low','Low'],['normal','Normal'],['medium','Medium'],['high','High']])}</label><label class="settings-wide">Configuration Parameters<textarea readonly rows="3">${esc((settings.extraConfig??[]).map(item=>`${item.key} = ${item.value}`).join('\n')||'No custom parameters reported')}</textarea></label>`),
    settingsOptionGroup('fiber','Fibre Channel NPIV','Virtual WWN assignments',`${settingsCheck('settings-npiv-disabled','Temporarily disable NPIV for this virtual machine',boolValue(settings.npivTemporaryDisabled),true)}<label>Number of WWNNs<input type="number" disabled value="${settings.npivDesiredNodeWwns??1}"></label><label>Number of WWPNs<input type="number" disabled value="${settings.npivDesiredPortWwns??4}"></label><label class="settings-wide">WWN assignments<textarea readonly rows="2">${esc((settings.npivNodeWwns??[]).join('\n'))}</textarea></label><label class="settings-wide">WWP assignments<textarea readonly rows="2">${esc((settings.npivPortWwns??[]).join('\n'))}</textarea></label>`)
  ].join('');
}

const renderVmSettingsEsxiParity=renderVmSettings;
renderVmSettings=function(settings){
  renderVmSettingsEsxiParity(settings);renderCompleteVmOptions(settings);
  const on=settings.powerState==='poweredOn',hardware=settings.hardware??{},controllerLabel=new Map((hardware.controllers??[]).map(c=>[String(c.id),c.label]));
  document.querySelectorAll('[data-settings-controller]').forEach(row=>row.querySelectorAll('select').forEach(select=>select.disabled=on));
  document.querySelectorAll('#settings-controllers .vm-settings-device:not([data-settings-controller])').forEach((row,index)=>{const item=(hardware.additionalDevices??[])[index];if(item?.id)row.dataset.settingsAdditional=String(item.id)});
  document.querySelectorAll('[data-settings-network]').forEach(row=>{
    const item=(hardware.networkAdapters??[]).find(n=>String(n.id)===row.dataset.settingsNetwork);if(!item)return;
    const grid=row.querySelector('.settings-detail-grid'),type=grid.querySelector('input[readonly]');if(type){type.replaceWith(Object.assign(document.createElement('select'),{innerHTML:[['VirtualE1000e','E1000e'],['VirtualSriovEthernetCard','SR-IOV passthrough'],['VirtualVmxnet3','VMXNET 3']].map(([v,l])=>`<option value="${v}" ${v===item.type?'selected':''}>${l}</option>`).join(''),disabled:on}));grid.querySelector('select:last-of-type').dataset.settingsNetworkType=''}
    const readonly=[...grid.querySelectorAll('input[readonly]')];if(readonly[0])readonly[0].replaceWith(Object.assign(document.createElement('select'),{innerHTML:[['generated','Automatic'],['manual','Manual']].map(([v,l])=>`<option value="${v}" ${v===(item.addressType??'generated')?'selected':''}>${l}</option>`).join(''),disabled:on}));const mac=grid.querySelector('input[readonly]');if(mac){mac.readOnly=on;mac.dataset.settingsNetworkMac=''}const selects=grid.querySelectorAll('select');if(selects[selects.length-1])selects[selects.length-1].dataset.settingsNetworkAddressType='';
  });
  document.querySelectorAll('[data-settings-cdrom]').forEach(row=>{const item=(hardware.cdDvdDrives??[]).find(d=>String(d.id)===row.dataset.settingsCdrom),grid=row.querySelector('.settings-detail-grid');if(!item||!grid)return;grid.insertAdjacentHTML('afterbegin',`<label>Type${settingsSelect('',/IsoBacking/i.test(item.backingType)?'iso':'host',[['host','Host device'],['iso','Datastore ISO file']])}</label>`);grid.insertAdjacentHTML('beforeend',`<label>Controller location<input readonly value="${esc(controllerLabel.get(String(item.controllerKey))??item.controllerKey??'Not reported')} · ${item.unitNumber??0}"></label>`)});
  document.querySelectorAll('[data-settings-video]').forEach(row=>{const item=(hardware.videoCards??[]).find(v=>String(v.id)===row.dataset.settingsVideo),grid=row.querySelector('.settings-detail-grid');if(!item||!grid)return;const display=grid.querySelector('input[readonly]');if(display)display.replaceWith(Object.assign(document.createElement('select'),{innerHTML:Array.from({length:10},(_,i)=>`<option ${i+1===(item.displayCount??1)?'selected':''}>${i+1}</option>`).join(''),disabled:on}));grid.insertAdjacentHTML('beforeend',`<label>3D renderer${settingsSelect('', 'automatic',[['automatic','Automatic'],['hardware','Hardware'],['software','Software']],on)}</label>`)});
  for(const id of ['settings-cpu','settings-cores','settings-memory','settings-cpu-hotadd','settings-memory-hotadd','settings-nested-hv','settings-iommu','settings-vpmc'])if($(id))$(id).disabled=on;
};

const collectVmSettingsEsxiParity=collectVmSettings;
collectVmSettings=function(){const output=collectVmSettingsEsxiParity();Object.assign(output,{bootRetryEnabled:$('settings-boot-retry')?.checked,bootRetryDelayMs:Number($('settings-boot-retry-delay')?.value||10)*1000,powerOffType:$('settings-poweroff-type')?.value,suspendType:$('settings-suspend-type')?.value,resetType:$('settings-reset-type')?.value,standbyAction:document.querySelector('[name="settings-standby"]:checked')?.value,toolsAfterPowerOn:$('settings-tools-poweron')?.checked,toolsAfterResume:$('settings-tools-resume')?.checked,toolsBeforeGuestStandby:$('settings-tools-suspend')?.checked,toolsBeforeGuestShutdown:$('settings-tools-shutdown')?.checked,toolsUpgradePolicy:$('settings-tools-upgrade')?.checked?'upgradeAtPowerCycle':'manual',disableAcceleration:$('settings-disable-acceleration')?.checked,enableLogging:$('settings-enable-logging')?.checked,debugInfo:$('settings-debug-info')?.value,swapPlacement:document.querySelector('[name="settings-swap"]:checked')?.value,latencySensitivity:$('settings-latency')?.value});return output};

state.vmSettingsRemovedDeviceIds=[];state.vmSettingsRemovalResourceId=null;
function vmSettingsRemovalAvailability(settings,item,kind){
  if(settings.powerState!=='poweredOn')return {disabled:false,reason:`Remove ${item.label}`};
  const controllers=settings.hardware?.controllers??[],controller=controllers.find(value=>String(value.id)===String(item.controllerKey)),controllerType=controller?.type??'';
  if(kind==='disk'||kind==='cdrom')return /SCSI|LsiLogic|ParaVirtual|AHCI|SATA|NVME/i.test(controllerType)?{disabled:false,reason:`Hot-remove ${item.label}` }:{disabled:true,reason:`${item.label} cannot be hot-removed from its ${/IDE/i.test(controllerType)?'IDE':'current'} controller.`};
  if(kind==='network'){
    const hotplugDisabled=(settings.extraConfig??[]).some(value=>value.key==='devices.hotplug'&&String(value.value).toLowerCase()==='false');
    return hotplugDisabled?{disabled:true,reason:'PCI hot-plug is disabled for this virtual machine.'}:{disabled:false,reason:`Hot-remove ${item.label}`};
  }
  if(kind==='usb-controller')return {disabled:false,reason:`Hot-remove ${item.label}; the guest operating system must support it.`};
  return {disabled:true,reason:`Power off the virtual machine to remove ${item.label}.`};
}
function addVmSettingsRemoveControl(row,item,availability){
  const summary=row?.querySelector('summary');if(!summary||!item?.id)return;
  const button=document.createElement('button');button.type='button';button.className='settings-remove-device';button.dataset.settingsRemoveDevice=String(item.id);button.disabled=availability.disabled;button.setAttribute('aria-label',`Remove ${item.label}`);button.title=availability.reason;button.textContent='×';summary.append(button);
  button.onclick=event=>{event.preventDefault();event.stopPropagation();const id=String(item.id),removed=new Set(state.vmSettingsRemovedDeviceIds),staged=removed.has(id);if(staged)removed.delete(id);else removed.add(id);state.vmSettingsRemovedDeviceIds=[...removed];row.classList.toggle('settings-device-removed',!staged);button.textContent=staged?'×':'↶';button.title=staged?`Remove ${item.label}`:`Undo removal of ${item.label}`;button.setAttribute('aria-label',button.title)};
}
const renderVmSettingsWithRemove=renderVmSettings;
renderVmSettings=function(settings){
  if(state.vmSettingsRemovalResourceId!==state.vmSettingsResourceId){state.vmSettingsRemovedDeviceIds=[];state.vmSettingsRemovalResourceId=state.vmSettingsResourceId}
  renderVmSettingsWithRemove(settings);const hardware=settings.hardware??{};
  for(const item of hardware.disks??[])addVmSettingsRemoveControl(document.querySelector(`[data-settings-disk="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,'disk'));
  for(const item of hardware.controllers??[])if(/AHCI|SATA|NVME|USB/i.test(item.type))addVmSettingsRemoveControl(document.querySelector(`[data-settings-controller="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,/USB/i.test(item.type)?'usb-controller':'controller'));
  for(const item of hardware.networkAdapters??[])addVmSettingsRemoveControl(document.querySelector(`[data-settings-network="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,'network'));
  for(const item of hardware.cdDvdDrives??[])addVmSettingsRemoveControl(document.querySelector(`[data-settings-cdrom="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,'cdrom'));
  for(const item of hardware.videoCards??[])addVmSettingsRemoveControl(document.querySelector(`[data-settings-video="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,'video'));
  for(const item of hardware.additionalDevices??[])if(/Sound|Audio|Floppy|Serial|Parallel|TPM/i.test(item.type))addVmSettingsRemoveControl(document.querySelector(`[data-settings-additional="${CSS.escape(String(item.id))}"]`),item,vmSettingsRemovalAvailability(settings,item,'additional'));
};
const collectVmSettingsWithRemove=collectVmSettings;
collectVmSettings=function(){const output=collectVmSettingsWithRemove(),removed=new Set(state.vmSettingsRemovedDeviceIds);for(const key of ['disks','controllers','networkAdapters','cdDvdDrives','videoCards'])output[key]=(output[key]??[]).filter(item=>!removed.has(String(item.id)));output.removedDeviceIds=[...removed];return output};
$('vm-settings-dialog').addEventListener('close',()=>{state.vmSettingsRemovedDeviceIds=[];state.vmSettingsRemovalResourceId=null});

